dm-inspector-panels:
﻿<div class="inspector-row-wrap">
  @if (versionHistoryFile; as file) {
    <section class="inspector-panel">
      <div class="inspector-head">
        <div>
          <h3>Version history</h3>
          <p>{{ file.name }}</p>
        </div>
        @if (canUpdateFiles) {
          <ui-button class="chip-btn" type="button" (click)="versionUpload.emit(file)">Upload new version</ui-button>
        }
        <ui-button class="inspector-close" type="button" aria-label="Close version history" title="Close" (click)="versionHistoryClose.emit()">x</ui-button>
      </div>
      <div class="governance-summary">
        <span class="governance-pill">{{ classificationLabel(file.classification) }}</span>
        <span class="governance-pill">{{ lifecycleLabel(file.lifecycleStatus) }}</span>
        <span class="governance-pill">{{ reviewLabel(file.reviewStatus) }}</span>
        <span>Review due: {{ file.reviewDueAtUtc ? (file.reviewDueAtUtc | date: 'mediumDate') : 'Not set' }}</span>
        @if (file.legalHold) {
          <span class="governance-pill governance-pill-danger">Legal hold</span>
        }
      </div>
      @if (file.reviewStatus && file.reviewStatus !== 'none') {
        <div class="governance-notice">
          <strong>Review {{ reviewLabel(file.reviewStatus) }}</strong>
          <span>Approver: {{ file.reviewApproverUserName || file.reviewApproverUserId || 'Not assigned' }}</span>
          @if (file.reviewRequestedAtUtc) {
            <span>Requested: {{ file.reviewRequestedAtUtc | date: 'medium' }}</span>
          }
          @if (file.reviewDecisionAtUtc) {
            <span>Decision: {{ file.reviewDecisionAtUtc | date: 'medium' }}</span>
          }
          @if (file.reviewComments) {
            <span>{{ file.reviewComments }}</span>
          }
        </div>
      }
      @if (file.legalHold) {
        <div class="governance-notice">
          <strong>This document is under legal hold.</strong>
          @if (file.legalHoldReason) {
            <span>{{ file.legalHoldReason }}</span>
          }
          <span>{{ file.legalHoldByUserName || file.legalHoldByUserId || 'System' }} · {{ file.legalHoldAtUtc | date: 'medium' }}</span>
        </div>
      }
      @if (canAdminUpdate) {
        <div class="governance-actions">
          @if (file.legalHold) {
            <ui-button class="chip-btn" type="button" (click)="legalHoldRelease.emit(file)">Release legal hold</ui-button>
          } @else {
            <ui-button class="chip-btn" type="button" (click)="legalHoldApply.emit(file)">Apply legal hold</ui-button>
          }
        </div>
      }
      @if (canUpdateFiles) {
        <div class="governance-actions">
          <ui-button class="chip-btn" type="button" (click)="reviewRequest.emit(file)">Request review</ui-button>
          @if (file.reviewStatus === 'requested') {
            <ui-button class="chip-btn" type="button" (click)="reviewApprove.emit(file)">Approve</ui-button>
            <ui-button class="chip-btn" type="button" (click)="reviewReject.emit(file)">Reject</ui-button>
          }
        </div>
      }
      @if (versionsLoading) {
        <div class="inspector-loading">
          <div class="spinner spinner-sm"></div>
          <span>Loading...</span>
        </div>
      } @else if (versions.length === 0) {
        <div class="inspector-empty">No version history yet.</div>
      } @else {
        <div class="inspector-list">
          @for (version of versions; track version.id) {
            <div class="inspector-item">
              <div class="inspector-item-info">
                <strong>Version {{ version.versionNumber }}</strong>
                @if (version.isCurrentVersion) {
                  <span class="version-badge">Current</span>
                }
                <span class="inspector-meta"
                  >{{ version.uploadedByUserName }} · {{ version.createdAtUtc | date: 'medium' }}</span
                >
                <span class="inspector-meta">{{ formatBytes(version.sizeBytes) }}</span>
              </div>
              <div class="inspector-actions">
                <ui-button class="chip-btn" type="button" (click)="versionDownload.emit(version)">Download</ui-button>
                @if (canUpdateFiles && !version.isCurrentVersion) {
                  <ui-button class="chip-btn" type="button" (click)="versionRestore.emit(version)">Restore</ui-button>
                }
              </div>
            </div>
          }
        </div>
      }
    </section>
  }

  @if (activityTarget; as target) {
    <section class="inspector-panel">
      <div class="inspector-head">
        <div>
          <h3>Activity</h3>
          <p>{{ target.name }}</p>
        </div>
        <ui-button class="inspector-close" type="button" aria-label="Close activity" title="Close" (click)="activityClose.emit()">x</ui-button>
      </div>
      @if (activityLoading) {
        <div class="inspector-loading">
          <div class="spinner spinner-sm"></div>
          <span>Loading...</span>
        </div>
      } @else if (activityItems.length === 0) {
        <div class="inspector-empty">No activity yet.</div>
      } @else {
        <div class="inspector-list">
          @for (event of activityItems; track event.id) {
            <div class="inspector-item">
              <div class="inspector-item-info">
                <strong>{{ event.action }}</strong>
                <span class="inspector-meta">{{ event.description }}</span>
                <span class="inspector-meta"
                  >{{ event.actorUserName }} · {{ event.createdAtUtc | date: 'medium' }}</span
                >
              </div>
            </div>
          }
        </div>
      }
    </section>
  }
</div>

dm-share-dialog:
@if (node || bulkNodes.length > 0) {
  <div class="share-overlay" (click)="closed.emit()">
    <div class="share-dialog" (click)="$event.stopPropagation()">
      <div class="share-header">
        <div class="share-header-info">
          @if (!isBulkShare && node?.resourceType === 'folder') {
            <svg width="20" height="20" viewBox="0 0 24 24" fill="#fbbf24" stroke="#f59e0b" stroke-width="1">
              <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z" />
            </svg>
          } @else if (isBulkShare) {
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#2563eb" stroke-width="1.8">
              <rect x="3" y="4" width="18" height="14" rx="2" />
              <path d="M7 8h10M7 12h6" />
            </svg>
          } @else {
            <div class="file-icon file-icon-sm" [class]="fileIconClass(node!)">{{ fileIconLabel(node!) }}</div>
          }
          <div>
            <h3>{{ isBulkShare ? 'Share selected items' : 'Share "' + node?.name + '"' }}</h3>
            <p class="share-subtitle">
              {{ isBulkShare ? bulkNodes.length + ' items selected' : node?.resourceType === 'folder' ? 'Folder' : node?.contentType }}
            </p>
          </div>
        </div>
        <ui-button type="button" class="share-close" title="Close share dialog" aria-label="Close share dialog" (click)="closed.emit()">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <line x1="18" y1="6" x2="6" y2="18" />
            <line x1="6" y1="6" x2="18" y2="18" />
          </svg>
        </ui-button>
      </div>

      @if (canShare) {
        <div class="share-add-section">
          <div class="share-add-label">Add people</div>
          <div class="share-add-row">
            @if (users().length > 0) {
              <ui-select class="share-user-select" [ngModel]="shareUserId()" (ngModelChange)="onShareUserSelected($event)">
                <option value="">Select a person...</option>
                @for (user of shareableUsers(); track user.id) {
                  <option [value]="user.id">{{ user.displayName || user.email }}</option>
                }
              </ui-select>
            } @else {
              <ui-input
                class="share-user-input"
                type="text"
                placeholder="User ID"
                [ngModel]="shareUserId()"
                (ngModelChange)="shareUserId.set($event)"
               />
              <ui-input
                class="share-user-input"
                type="text"
                placeholder="Display name"
                [ngModel]="shareUserName()"
                (ngModelChange)="shareUserName.set($event)"
               />
            }
            <ui-select
              class="share-perm-select"
              [ngModel]="sharePermission()"
              (ngModelChange)="sharePermission.set($event)"
            >
              <option value="view">Viewer</option>
              <option value="edit">Editor</option>
            </ui-select>
            <ui-button
              class="share-btn-add"
              type="button"
              [disabled]="shareSaving() || !shareUserId().trim()"
              (click)="addShareRecipient()"
            >
              Add
            </ui-button>
          </div>
          @if (shareRecipients().length > 0) {
            <div class="share-recipient-list">
              @for (recipient of shareRecipients(); track recipient.userId) {
                <div class="share-recipient-chip">
                  <div class="share-avatar share-avatar-sm">{{ userInitials(recipient.userName) }}</div>
                  <span>{{ recipient.userName }}</span>
                  <strong>{{ permissionLabel(recipient.permissionLevel) }}</strong>
                  <ui-button type="button" (click)="removeShareRecipient(recipient.userId)" title="Remove selected person">
                    <svg
                      width="13"
                      height="13"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      stroke-width="2.2"
                    >
                      <line x1="18" y1="6" x2="6" y2="18" />
                      <line x1="6" y1="6" x2="18" y2="18" />
                    </svg>
                  </ui-button>
                </div>
              }
            </div>
            <ui-button class="share-btn-submit" type="button" [disabled]="shareSaving()" (click)="submitShare()">
              {{
                shareSaving()
                  ? 'Sharing...'
                  : 'Share with ' + shareRecipients().length + ' person' + (shareRecipients().length > 1 ? 's' : '')
              }}
            </ui-button>
          }
          @if (shareError()) {
            <div class="share-error">{{ shareError() }}</div>
          }
        </div>
      }

      @if (!isBulkShare) {
        <div class="share-link-section">
          <div class="share-access-label">Shareable link</div>
          <div class="share-link-row">
            <ui-input
              class="share-link-input"
              type="text"
              readonly
              [value]="shareableLink() || 'Generate a link to this item'"
             />
            @if (shareableLink()) {
              <ui-button class="share-btn-add" type="button" (click)="copyShareableLink()">
                {{ shareLinkCopied() ? 'Copied' : 'Copy' }}
              </ui-button>
            } @else {
              <ui-button class="share-btn-add" type="button" (click)="generateShareableLink()">Generate</ui-button>
            }
          </div>
        </div>
      }

      <div class="share-access-section">
        <div class="share-access-label">{{ isBulkShare ? 'Bulk share' : 'People with access' }}</div>
        @if (isBulkShare) {
          <div class="share-empty">Selected items will be shared with the people added above.</div>
        } @else if (sharesLoading()) {
          <div class="share-loading">Loading...</div>
        } @else if (shares().length === 0) {
          <div class="share-empty">
            Only workspace members can access this item. Share it to give direct access to individuals.
          </div>
        } @else {
          <div class="share-people-list">
            @for (share of shares(); track share.id) {
              <div class="share-person-row">
                <div class="share-avatar">{{ userInitials(share.targetUserName) }}</div>
                <div class="share-person-info">
                  <strong>{{ share.targetUserName }}</strong>
                  <span class="share-person-meta"
                    >Shared by {{ share.sharedByUserName }} ˇ {{ share.createdAtUtc | date: 'mediumDate' }}</span
                  >
                </div>
                <div class="share-person-right">
                  <span class="share-perm-badge">{{ permissionLabel(share.permissionLevel) }}</span>
                  @if (canShare) {
                    <ui-button
                      class="share-remove-btn"
                      type="button"
                      (click)="removeShareItem(share.id)"
                      title="Remove access"
                    >
                      <svg
                        width="14"
                        height="14"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        stroke-width="2"
                      >
                        <line x1="18" y1="6" x2="6" y2="18" />
                        <line x1="6" y1="6" x2="18" y2="18" />
                      </svg>
                    </ui-button>
                  }
                </div>
              </div>
            }
          </div>
        }
      </div>
    </div>
  </div>
}

dm-crud-dialog:
@if (dialogState; as ds) {
  <div class="dialog-overlay" (click)="closed.emit()">
    <div class="dialog-card" (click)="$event.stopPropagation()">
      <div class="dialog-head">
        <h3>{{ ds.title }}</h3>
        <ui-button class="dialog-close" type="button" (click)="closed.emit()">�</ui-button>
      </div>

      @if (ds.mode === 'file-upload' || ds.mode === 'file-version-upload') {
        <label class="upload-zone">
          <ui-file-upload [multiple]="ds.mode === 'file-upload'" (selected)="onFilePick($event)" />
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#9ca3af" stroke-width="1.5">
            <polyline points="16 16 12 12 8 16" />
            <line x1="12" y1="12" x2="12" y2="21" />
            <path d="M20.39 18.39A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.3" />
          </svg>
          <span class="upload-label">
            @if (pickedFiles.length > 0) {
              {{ pickedFiles.length }} file(s) selected
            } @else {
              {{ ds.mode === 'file-version-upload' ? 'Click to choose a new version' : 'Click to choose files' }}
            }
          </span>
        </label>
        @if (pickedFiles.length > 0) {
          <div class="picked-list">
            @for (f of pickedFiles; track f.name) {
              <div class="picked-item">
                <span>{{ f.name }}</span>
                <span class="picked-size">{{ formatBytes(f.size) }}</span>
              </div>
            }
          </div>
        }
      }

      @if (
        ds.mode === 'folder-create' ||
        ds.mode === 'folder-rename' ||
        ds.mode === 'folder-copy' ||
        ds.mode === 'file-create' ||
        ds.mode === 'file-rename'
      ) {
        <label class="dialog-field">
          <span>{{ ds.mode.startsWith('file') ? 'File name' : 'Folder name' }}</span>
          <ui-input
            type="text"
            [(ngModel)]="ds.name"
            [placeholder]="ds.mode === 'folder-copy' ? 'Optional � leave blank to auto-name' : ''"
           />
        </label>
      }

      @if (ds.mode === 'file-create') {
        <label class="dialog-field">
          <span>Content type</span>
          <ui-select [(ngModel)]="ds.contentType">
            <option value="text/plain">Plain text (.txt)</option>
            <option value="application/json">JSON</option>
            <option value="text/html">HTML</option>
            <option value="text/csv">CSV</option>
            <option value="application/xml">XML</option>
            <option value="application/octet-stream">Binary / Other</option>
          </ui-select>
        </label>
      }

      @if (
        ds.mode === 'file-create' ||
        ds.mode === 'file-upload' ||
        ds.mode === 'file-version-upload' ||
        ds.mode === 'file-rename'
      ) {
        <label class="dialog-field">
          <span>Category</span>
          <ui-input type="text" [(ngModel)]="ds.category" placeholder="Optional category"  />
        </label>
        <label class="dialog-field">
          <span>Description</span>
          <ui-textarea rows="3" [(ngModel)]="ds.description" placeholder="Optional description"></ui-textarea>
        </label>
        <label class="dialog-field">
          <span>Tags</span>
          <ui-input type="text" [(ngModel)]="ds.tagsText" placeholder="Comma-separated tags"  />
        </label>
        <label class="dialog-field">
          <span>Classification</span>
          <ui-select [(ngModel)]="ds.classification">
            <option value="public">Public</option>
            <option value="internal">Internal</option>
            <option value="confidential">Confidential</option>
            <option value="restricted">Restricted</option>
          </ui-select>
        </label>
        <label class="dialog-field">
          <span>Lifecycle status</span>
          <ui-select [(ngModel)]="ds.lifecycleStatus">
            <option value="draft">Draft</option>
            <option value="active">Active</option>
            <option value="approved">Approved</option>
            <option value="obsolete">Obsolete</option>
            <option value="archived">Archived</option>
          </ui-select>
        </label>
        <label class="dialog-field">
          <span>Review due</span>
          <ui-date-picker [(ngModel)]="ds.reviewDueAtUtc"  />
        </label>
      }

      @if (ds.mode === 'file-review-request') {
        <div class="dialog-confirm dialog-confirm-success">
          <strong>Request review for "{{ ds.node?.name }}"?</strong>
          <p>Assign one approver to make the document decision.</p>
        </div>
        <label class="dialog-field">
          <span>Approver user ID</span>
          <ui-input type="text" [(ngModel)]="ds.reviewApproverUserId" placeholder="User ID"  />
        </label>
        <label class="dialog-field">
          <span>Approver name</span>
          <ui-input type="text" [(ngModel)]="ds.reviewApproverUserName" placeholder="Optional display name"  />
        </label>
        <label class="dialog-field">
          <span>Comments</span>
          <ui-textarea rows="3" [(ngModel)]="ds.reviewComments" placeholder="Optional review note"></ui-textarea>
        </label>
      }

      @if (ds.mode === 'file-review-approve' || ds.mode === 'file-review-reject') {
        <div class="dialog-confirm" [class.dialog-confirm-success]="ds.mode === 'file-review-approve'" [class.dialog-confirm-warn]="ds.mode === 'file-review-reject'">
          <strong>{{ ds.mode === 'file-review-approve' ? 'Approve' : 'Reject' }} review for "{{ ds.node?.name }}"?</strong>
          <p>{{ ds.mode === 'file-review-approve' ? 'Approval sets the document lifecycle to approved.' : 'Rejection records the decision and leaves lifecycle unchanged.' }}</p>
        </div>
        <label class="dialog-field">
          <span>Decision comments</span>
          <ui-textarea rows="3" [(ngModel)]="ds.reviewComments" placeholder="Optional decision note"></ui-textarea>
        </label>
      }

      @if (ds.mode === 'file-legal-hold') {
        <div class="dialog-confirm dialog-confirm-warn">
          <strong>Apply legal hold to "{{ ds.node?.name }}"?</strong>
          <p>This prevents trash, permanent delete, and retention purge until the hold is released.</p>
        </div>
        <label class="dialog-field">
          <span>Reason</span>
          <ui-textarea rows="3" [(ngModel)]="ds.legalHoldReason" placeholder="Reason for legal hold"></ui-textarea>
        </label>
      }

      @if (ds.mode === 'file-release-legal-hold') {
        <div class="dialog-confirm dialog-confirm-success">
          <strong>Release legal hold from "{{ ds.node?.name }}"?</strong>
          <p>The document can be deleted or purged again after release.</p>
        </div>
        <label class="dialog-field">
          <span>Release note</span>
          <ui-textarea rows="3" [(ngModel)]="ds.legalHoldReason" placeholder="Optional release note"></ui-textarea>
        </label>
      }

      @if ((ds.mode === 'file-create' || ds.mode === 'file-upload') && ds.scope) {
        <div class="dialog-field">
          <span>Scope</span>
          <div class="scope-summary">
            <strong>{{ scopeLabel(ds.scope) }}</strong>
            <small>Uses the selected Document Management company scope.</small>
          </div>
        </div>
      }

      @if (
        ds.mode === 'folder-move' ||
        ds.mode === 'folder-copy' ||
        ds.mode === 'folder-restore' ||
        ds.mode === 'bulk-move' ||
        ds.mode === 'file-move' ||
        ds.mode === 'file-copy'
      ) {
        <label class="dialog-field">
          <span>Destination folder</span>
          <ui-select [(ngModel)]="ds.destinationFolderId" valueType="string">
            <option value="" >Root</option>
            @for (folder of destinationFolders; track folder.id) {
              <option [value]="folder.id">{{ folderLabel(folder) }}</option>
            }
          </ui-select>
        </label>
      }

      @if (ds.mode === 'folder-delete' || ds.mode === 'file-delete') {
        <div class="dialog-confirm dialog-confirm-warn">
          <strong>Move "{{ ds.node?.name }}" to trash?</strong>
          <p>
            {{
              ds.mode === 'folder-delete'
                ? 'The folder and all its contents will be soft-deleted.'
                : 'The file will be soft-deleted and can be restored from trash.'
            }}
          </p>
        </div>
      }

      @if (ds.mode === 'file-restore') {
        <div class="dialog-confirm dialog-confirm-success">
          <strong>Restore "{{ ds.node?.name }}"?</strong>
          <p>The file will be moved back to its original location.</p>
        </div>
      }

      <div class="dialog-actions">
        <ui-button  type="button" (click)="closed.emit()" variant="ghost">Cancel</ui-button>
        <ui-button  type="button" [disabled]="saving" (click)="submitted.emit()" variant="primary">
          @if (saving) {
            Saving...
          } @else if (ds.mode === 'folder-delete' || ds.mode === 'file-delete') {
            Move to Trash
          } @else if (ds.mode === 'file-legal-hold') {
            Apply Hold
          } @else if (ds.mode === 'file-release-legal-hold') {
            Release Hold
          } @else if (ds.mode === 'file-review-request') {
            Request Review
          } @else if (ds.mode === 'file-review-approve') {
            Approve
          } @else if (ds.mode === 'file-review-reject') {
            Reject
          } @else if (ds.mode === 'file-upload' || ds.mode === 'file-version-upload') {
            Upload {{ pickedFiles.length > 0 ? '(' + pickedFiles.length + ')' : '' }}
          } @else {
            Save
          }
        </ui-button>
      </div>
    </div>
  </div>
}
